local item_lib = require("items")
local function staging(e)
 return e.qglobals.coldainWarPhase=="staging" and e.qglobals.coldainWarStaging=="active"
end

function event_signal(e)
 if e.signal==1 and staging(e) then eq.start(120) end
end
function event_waypoint_arrive(e)
 if not staging(e) then return end
 if e.wp==1 then
  e.self:Say("Excellent! All of your commanders have reported to the Dain, and none too soon mind you. We are getting reports of Kromrif troop movement in the area and final preparations must be made. Follow me and the Seneschal will brief you.")
  eq.spawn_condition("greatdivide",0,25,1)
 elseif e.wp==2 then
  eq.spawn_condition("greatdivide",0,23,1)
  eq.spawn_condition("greatdivide",0,148,1)
 elseif e.wp==5 then
  eq.get_entity_list():GetNPCByNPCTypeID(2000963):Say("With all due respect, Seneschal, I feel my men are best suited for the eastern post. If the outlander has rounded up enough soldiers to hold 'em off from the south then they'll definitely test us in the gorge. We'll be needin' a solid defense there.")
 elseif e.wp==6 then
  eq.get_entity_list():GetNPCByNPCTypeID(2000965):Say("Very well, Garadain. The eastern post is yours. I'll place Kargin and his bowmen on the hill to the west, and Churn, you'll station your troops up near the caves just past them.")
  eq.set_timer("ChurnSay",5000)
 elseif e.wp==7 then
  e.self:Say("Excuse me, Seneschal Aldikar, you instructed me to report to you when the outlander returned. I have brought him.")
  eq.get_entity_list():GetNPCByNPCTypeID(2000965):Say("Perfect timing, outlander. Please be seated and listen carefully. Badain, yer dismissed.")
  eq.signal(2000965,1)
 elseif e.wp==8 then
  e.self:Say("Sir, yessir!")
 end
end
function event_timer(e)
 if e.timer=="ChurnSay" then
  eq.stop_timer(e.timer)
  if staging(e) then eq.get_entity_list():GetNPCByNPCTypeID(2000960):Say("Understood sir.") end
 end
end
